import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormControl } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import {
  DateAdapter,
  MAT_DATE_FORMATS,
  MAT_DATE_LOCALE,
} from '@angular/material/core';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTable, MatTableDataSource } from '@angular/material/table';
import { DialogDetailComponent } from 'src/app/modules/reports/pages/dialog-detail/dialog-detail.component';
import { ReportsService } from 'src/app/modules/reports/reports.service';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-attendance-summary-report',
  templateUrl: './attendance-summary-report.component.html',
  styleUrls: ['./attendance-summary-report.component.scss'],
  providers: [
    {
      provide: DateAdapter,
      useClass: MomentDateAdapter,
      deps: [MAT_DATE_LOCALE],
    },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class AttendanceSummaryReportComponent implements OnInit {
  List: any[] = [];
  @ViewChild('table') table!: ElementRef;

  employeelist: any;
  Users: any;
  minDate = new Date('1950/01/01');
  today = new Date();
  maxDate = new Date(this.today.getFullYear(), this.today.getMonth(), this.today.getDate() - 1);
  minToDate: any;
  pageLoading = true;
  displayLength: boolean = false;
  searchControl = new FormControl('');
  filteredEmployeeList: any = [];
  constructor(
    public reportsService: ReportsService,
    public datePipe: DatePipe,
    public formBuilder: UntypedFormBuilder,
    public dialog: MatDialog,
    private pdfService: PdfHeaderService,
  ) { }

  @ViewChild(MatTable) tableOne: MatTable<any> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  filter = new UntypedFormControl();
  userSession: any;
  monthdata: any;
  year: any;
  months = [
    { id: 0, month: 'Jan' },
    { id: 1, month: 'Feb' },
    { id: 2, month: 'Mar' },
    { id: 3, month: 'Apr' },
    { id: 4, month: 'May' },
    { id: 5, month: 'Jun' },
    { id: 6, month: 'Jul' },
    { id: 7, month: 'Aug' },
    { id: 8, month: 'Sep' },
    { id: 9, month: 'Oct' },
    { id: 10, month: 'Nov' },
    { id: 11, month: 'Dec' },
  ];
  searchForm = this.formBuilder.group({
    fromDate: [this.maxDate],
    toDate: [this.maxDate],
    Users: ['0'],
  });
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns: string[] = [
    'sno',
    'empname',
    'empcode',
    'attendancedate',
    'reporting_manager',
    'firstlogintime',
    'earlyleave',
    'lastlogouttime',
    'totalhours',
    'productivehours',
    'ot',
    'ph',
    'action',
  ];
  isLoading = false;
  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.Searchform();
    this.getEmployeelist();
    this.searchForm
      .get('fromDate')
      ?.valueChanges.subscribe((selectedValue: any) => {
        if (selectedValue != null) {
          this.minToDate = selectedValue._d;
        }
      });
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmployees(searchText);
    });
  }

  getEmployeelist() {
    let obj = {
      remployee_id: this.userSession.id,
    };
    this.reportsService
      .getReportsuserEmployeesList(obj)
      .subscribe((res: any) => {
        if (res.status) {
          this.employeelist = [];
          this.employeelist = res.data;
          this.filteredEmployeeList = this.employeelist;
          this.searchForm.controls.user.setValue('0');
        }
      });
  }
  //All Employees API
  Searchform() {
    this.List = [];
    this.dataSource = new MatTableDataSource(this.List);

    let fromDate = this.datePipe.transform(
      this.searchForm.controls.fromDate.value,
      'y-MM-d'
    );
    let toDate = this.datePipe.transform(
      this.searchForm.controls.toDate.value,
      'y-MM-d'
    );
    let userId = this.searchForm.controls.Users.value;
    if (userId == '0') {
      userId = null;
    }
    let data = {
      rempid: this.userSession.id,
      employee: userId,
      fromdate: fromDate,
      todate: toDate,
    };
    this.isLoading = true;
    this.reportsService
      .getAttendanceSummaryReportForReportsuser(data)
      .subscribe(
        (res: any) => {
          this.List = res.data;
          if (res.status) {
            this.List.forEach((e: any) => {
              if (e.breaks != null) {
                e.breaks = e.breaks.split(',');
              }
            });
            this.displayLength = true
          }

          this.isLoading = false;
          this.dataSource = new MatTableDataSource(this.List);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
        },
        (error) => {
          this.isLoading = false;
          error.error.text;
        }
      );
  }

  resetform() {
    this.dataSource.data = [];
    this.searchForm.reset();
    this.searchForm.controls.fromDate.setValue(this.maxDate);
    this.searchForm.controls.toDate.setValue(this.maxDate);
    this.searchForm.controls.Users.setValue('0');
  }
  openDialog(item: any): void {
    const dialogRef = this.dialog.open(DialogDetailComponent, {
      width: '1200px',
      position: { top: `70px` },
      data: { attendanceid: item.id ,item:item},
    });
    dialogRef.afterClosed().subscribe((result) => { });
  }


  exportAsXLSX() {

    let fromdate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-yyyy");
    let todate = this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-yyyy");
    const formatTime = (input: string) => {
      if (!input) return '-';
      if (input.includes(' ')) {
        const [datePart, timePart] = input.split(' ');
        return `${datePart} ${timePart.substring(0, 5)}`;
      } else {
        return input.substring(0, 5);
      }
    };
    const exportData = this.List.map((row, index) => ({
      "S.No": index + 1,
      "Employee Name": row.empname,
      "Emp. ID": row.empcode,
      "Date": this.datePipe.transform(row.attendancedate, "dd-MM-yyyy"),
      "First In": this.datePipe.transform(row.firstlogintime, "dd-MM-yyyy HH:mm"),
      "Last Out": this.datePipe.transform(row.lastlogouttime, "dd-MM-yyyy HH:mm"),
      "Early Leave": formatTime(row.early_leaving_time),
      "Total Hours": formatTime(row.totalhours),
      "Productive Hours": formatTime(row.productivehours),
      "OT Hours": formatTime(row.overtime_minutes),
      "Permission Hours": formatTime(row.permissionhours)
    }));
  
    const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
  
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Attendance_Summary_Report');
    XLSX.writeFile(wb, fromdate + " - " + todate + " - " + 'Attendance_Summary_Report.xlsx');
  
  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  filterEmployees(searchText: any) {
    this.filteredEmployeeList = this.employeelist.filter((val: any) =>
      val.empname.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployeeList.length <= 0) {
      this.searchControl.setValue('');
    }
  }

  generatePDF() {
  
    const doc = new jsPDF({ orientation: 'landscape' });
    const reportName = 'Attendance Summary Report';
    let fromdate = (this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY"));
    let todate = (this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY"));
    const formatTime = (input: string) => {
      if (!input) return '-';
      if (input.includes(' ')) {
        const [datePart, timePart] = input.split(' ');
        return `${datePart} ${timePart.substring(0, 5)}`;
      } else {
        return input.substring(0, 5);
      }
    };
    let manager = '';
    let locationName = '';
    let reportDate = fromdate +' to '+ todate;
    const headerHeight = 35;
    const tableData = this.List.map((emp:  { empname: any;  empcode:any;  attendancedate: any;   firstlogintime: any ;
                                             lastlogouttime: any; early_leaving_time:any;   totalhours: any; productivehours: any; overtime_minutes: any;
                                             permissionhours: any}, index: number) => [
      index + 1,
      emp.empname,
      emp.empcode,
      this.datePipe.transform(emp.attendancedate, "dd-MM-yyyy"),
      this.datePipe.transform(emp.firstlogintime, "dd-MM-yyyy HH:mm"),
      this.datePipe.transform(emp.lastlogouttime, "dd-MM-yyyy HH:mm"),
      formatTime(emp.early_leaving_time),
      formatTime(emp.totalhours),
      formatTime(emp.productivehours),
      formatTime(emp.overtime_minutes),
      formatTime(emp.permissionhours),
    ]);
          autoTable(doc, {
            head: [['S.No.','Emp. Name', 'Emp. ID', 'Date','First In','Last Out', 'Early Leave','Total Hrs','Productive Hrs','OT Hrs','Permission Hrs']],
            body:tableData,
            startY: headerHeight,
            styles: { fontSize: 10 },
            headStyles: { fontSize: 11 },
            margin: { top: headerHeight },
            didDrawPage: (data) => {
              this.pdfService.generatePDFHeader(doc, reportName,locationName,manager,reportDate,false,false);
              doc.setFontSize(10);
              doc.setTextColor(40);
            }
          });
       doc.save('attendance_summary_report.pdf');
  } 
}

