import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormControl } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import {
  DateAdapter,
  MAT_DATE_FORMATS,
  MAT_DATE_LOCALE,
} from '@angular/material/core';
import { MatDatepickerInputEvent } from '@angular/material/datepicker';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { AttendanceService } from 'src/app/modules/attendance/attendance.service';
import { ExcelServiceService } from 'src/app/modules/reports/excel-service.service';
import { ReportsService } from 'src/app/modules/reports/reports.service';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-attendance-late-report',
  templateUrl: './attendance-late-report.component.html',
  styleUrls: ['./attendance-late-report.component.scss'],
  providers: [
    {
      provide: DateAdapter,
      useClass: MomentDateAdapter,
      deps: [MAT_DATE_LOCALE],
    },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class AttendanceLateReportComponent implements OnInit {
  List: any[] = [];
  employeelist: any;
  Users: any;
  minDate = new Date('2020/01/01');
  maxDate = new Date();
  userSession: any;
  date = new Date();
  firstDay: any;
  lastDay: any;
  startDate = new Date(this.date.getFullYear(), this.date.getMonth(), 1);
  endDate = new Date(this.date.getFullYear(), this.date.getMonth() + 1, 0);
  dateDayArray: any = [];
  obj: any;
  headersList: any = [];
  @ViewChild('table') table!: ElementRef;
  shiftDataList: any;
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  pageLoading = true;
  searchControl = new FormControl('');
  searchControlforshift = new FormControl('');
  filteredEmployeeList: any = [];
  filteredShiftList: any = [];
  constructor(
    public reportsService: ReportsService,
    public datePipe: DatePipe,
    public formBuilder: UntypedFormBuilder,
    public dialog: MatDialog,
    private excelService: ExcelServiceService,
    private attendanceService: AttendanceService,
    private dateESI: DatePipe,
    private pdfService: PdfHeaderService,
  ) {
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = new Date();
    this.minToDate.setDate(this.currentDate.getDate() - 90);
    this.maxToDate = new Date();
  }

  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sorter!: MatSort;
  filter = new UntypedFormControl();
  searchForm = this.formBuilder.group({
    fromDate: [new Date()],
    toDate: [new Date()],
    user: ['0'],
    shift: ['0'],
  });
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns: string[] = [
    'sno',
    'empid',
    'empname',
    'shift',
    'fromdate',
    'todate',
    'intime',
    'latehours',
  ];
  isLoading = false;

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.getEmployeelist();
    this.getActiveShiftIds();
    this.Searchform();
  }

  getActiveShiftIds() {
    this.attendanceService.getActiveShiftIds().subscribe((res) => {
      if (res.status) {
        this.shiftDataList = res.data;
        this.filteredShiftList = this.shiftDataList;
        this.searchForm.controls.shift.setValue('0');
      }
    });
  }

  getEmployeelist() {
    let obj = {
      remployee_id: this.userSession.id,
    };
    this.reportsService
      .getReportsuserEmployeesList(obj)
      .subscribe((res: any) => {
        if (res.status) {
          this.employeelist = [];
          this.employeelist = res.data;
          this.filteredEmployeeList = this.employeelist;
          this.searchForm.controls.user.setValue('0');
        }
      });
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmployees(searchText);
    });
    this.searchControlforshift.valueChanges.subscribe(searchText => {
      this.filterShifts(searchText);
    })
  }
  //All Employees API
  Searchform() {
    this.List = [];
    this.dataSource = new MatTableDataSource(this.List);
    let fromDate = this.datePipe.transform(
      this.searchForm.controls.fromDate.value,
      'y-MM-dd'
    );
    let toDate = this.datePipe.transform(
      this.searchForm.controls.toDate.value,
      'y-MM-dd'
    );
    let userId =
      this.searchForm.controls.user.value == '0'
        ? null
        : this.searchForm.controls.user.value;
    let shift =
      this.searchForm.controls.shift.value == '0'
        ? null
        : this.searchForm.controls.shift.value;

    let data = {};
    data = {
      rempid: this.userSession.id,
      employee_id: userId,
      shift_id: shift,
      from_date: fromDate,
      to_date: toDate,
    };

    this.isLoading = true;

    this.reportsService
      .getEmployeeLateAttendanceReportForReportsuser(data)
      .subscribe(
        (res: any) => {
          this.headersList = [];
          this.List = [];
          if (res.status) {
            let i = 0;
            this.List = res.data;
            this.isLoading = false;
            this.dataSource = new MatTableDataSource(this.List);
            this.dataSource.paginator = this.paginator;
            this.pageLoading = false;
          }
        },
        (error) => {
          this.isLoading = false;
          error.error.text;
        }
      );
  }

  resetform() {
    this.dataSource.data = [];
    this.searchForm.reset();
    this.searchForm.controls.fromDate.setValue(new Date());
    this.searchForm.controls.toDate.setValue(new Date());
    this.searchForm.controls.user.setValue('0');
    this.searchForm.controls.shift.setValue('0');
    this.Searchform();
  }

  exportAsXLSX() {
    let fromDate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-yyyy");
    let toDate = this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-yyyy");
    const formatTime = (input: string) => {
      if (!input) return '-';
      if (input.includes(' ')) {
        const [datePart, timePart] = input.split(' ');
        return `${datePart} ${timePart.substring(0, 5)}`;
      } else {
        return input.substring(0, 5);
      }
    };
    const headerRow = [
      { A: `Report Name: Late Attendance Report`, B: `From Date: ${fromDate}`, C: `To Date: ${toDate}` }
    ];

    const exportData = this.List.map((row, index) => ({
      "S.No": index + 1,
      "Employee ID": row.empid,
      "Employee Name": row.empname,
      "Shift": row.shiftname,
      "Date": this.datePipe.transform(row.attendancedate, "dd-MM-yyyy"),
      "Shift InTime": formatTime(row.shiftstarttime),
      "In Time": formatTime(row.actual_in_time),
      "Late Hours": formatTime(row.latehours),
   
    }));

  const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(headerRow, { skipHeader: true });

  XLSX.utils.sheet_add_json(ws, exportData, { origin: 'A2', skipHeader: false });

  const wb: XLSX.WorkBook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Late_attendance_Report');
  
    XLSX.writeFile(wb, fromDate + '-' + toDate + '-' + 'Late_attendance_Report.xlsx');

  }
  fromDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.minToDate = event.value;
    if (event.value !== null) {
      this.maxToDate = new Date();
      // event!.value.getFullYear(),
      // event!.value.getMonth(),
      // event!.value.getDate() + 30
    }
  }

  toDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.maxFromDate = event.value;
    // if (event.value !== null) {
    //   this.minFromDate = new Date(
    //     event!.value.getFullYear(),
    //     event!.value.getMonth(),
    //     event!.value.getDate() - 30
    //   );
    // }
  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }


  filterEmployees(searchText: any) {
    this.filteredEmployeeList = this.employeelist.filter((val: any) =>
      val.empname.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployeeList.length <= 0) {
      this.searchControl.setValue('');
    }
  }
  filterShifts(searchText: any) {
    this.filteredShiftList = this.shiftDataList.filter((val: any) =>
      val.shiftname.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredShiftList.length <= 0) {
      this.searchControlforshift.setValue('');
    }
  }
  generatePDF() {
  
    const doc = new jsPDF({ orientation: 'landscape' });
    const reportName = 'Late Attendance Report';
    let fromdate = (this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY"));
    let todate = (this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY"));
    const formatTime = (input: string) => {
      if (!input) return '-';
      if (input.includes(' ')) {
        const [datePart, timePart] = input.split(' ');
        return `${datePart} ${timePart.substring(0, 5)}`;
      } else {
        return input.substring(0, 5);
      }
    };
    let manager = '';
    let locationName = '';
    let reportDate = fromdate +' to '+ todate;
    const headerHeight = 33;
   
    const tableData = this.List.map((emp:  {
       empid:any;
       empname: any;    
       shiftname: any;   
       attendancedate: any ;
       shiftstarttime: any;   
       actual_in_time: any; 
       latehours: any; 
    }, index: number) => [

      index + 1,
      emp.empid,
      emp.empname,
      emp.shiftname,
      this.datePipe.transform(emp.attendancedate, "dd-MM-yyyy"),
      formatTime(emp.shiftstarttime),
        formatTime(emp.actual_in_time),
          formatTime(emp.latehours)
    ]);
          autoTable(doc, {
            head: [['S.No.', 'Emp.ID','Emp.Name', 'Shift','Date','Shift InTime','In Time','Late Hours']],
            body:tableData,
            startY: headerHeight,
            styles: { fontSize: 10 },
            headStyles: { fontSize: 11 },
            margin: { top: headerHeight },
            didDrawPage: (data) => {
              this.pdfService.generatePDFHeader(doc, reportName,locationName,manager,reportDate,false,false);
              doc.setFontSize(10);
              doc.setTextColor(40);
            }
          });
       doc.save('late_attendance_report.pdf');
  } 
}
